import {createEventsController} from './events.js';
import {SUPABASE_URL,SUPABASE_KEY} from './config.js';
import {createTogetherClient} from './client.js';
const $=id=>document.getElementById(id);
let events;
let api,mode='login',user=null,profile=null,generation=0;
function notify(message,error=false){$('notice').textContent=message;$('notice').classList.toggle('error',error);$('notice').hidden=false;}
function message(e){const map={invalid_credentials:'Nieprawidłowy e-mail lub hasło.',email_not_confirmed:'Najpierw potwierdź adres e-mail w wiadomości od Supabase.',over_email_send_rate_limit:'Osiągnięto limit wiadomości. Odczekaj kilka minut.',over_request_rate_limit:'Zbyt wiele prób. Spróbuj ponownie później.',user_already_exists:'Nie można zarejestrować tego adresu. Spróbuj się zalogować.',signup_disabled:'Rejestracja jest wyłączona w Supabase.',weak_password:'Hasło nie spełnia wymagań Supabase.',session_expired:'Sesja wygasła. Zaloguj się ponownie.'};if(e.code==='42501')return 'Baza odrzuciła operację ze względu na uprawnienia.';return map[e.code]||e.message||'Coś poszło nie tak. Spróbuj ponownie.';}
async function busy(element,action){const buttons=[...element.querySelectorAll('button')];buttons.forEach(b=>b.disabled=true);try{await action();}catch(e){notify(message(e),true);if(e.status===401){generation++;showAuth();}}finally{buttons.forEach(b=>b.disabled=false);}}
function showAuth(){events?.clear();user=null;profile=null;$('auth-view').hidden=false;$('profile-view').hidden=true;$('full-name').value='';$('username').value='';$('account-email').textContent='';$('user-id').textContent='';$('test-result').hidden=true;$('other-id').value='';}
function selectMode(next){mode=next;const signup=mode==='signup';$('login-tab').classList.toggle('active',!signup);$('signup-tab').classList.toggle('active',signup);$('login-tab').setAttribute('aria-pressed',String(!signup));$('signup-tab').setAttribute('aria-pressed',String(signup));$('auth-heading').textContent=signup?'Zacznijmy od Ciebie':'Miło Cię widzieć';$('auth-description').textContent=signup?'Załóż konto i stwórz swój prywatny profil.':'Zaloguj się i wróć do swojego miejsca.';$('auth-submit').replaceChildren(document.createTextNode(signup?'Utwórz konto':'Zaloguj się'));$('repeat-wrap').hidden=!signup;$('repeat-password').required=signup;$('password').minLength=signup?8:1;$('password').autocomplete=signup?'new-password':'current-password';$('password').value='';$('repeat-password').value='';$('notice').hidden=true;}
function paintProfile(){const name=profile?.full_name||user?.email?.split('@')[0]||'Cześć';$('welcome').textContent=`Cześć, ${name}!`;$('avatar').textContent=name.slice(0,1).toUpperCase();$('account-email').textContent=user.email||'';$('full-name').value=profile?.full_name||'';$('username').value=profile?.unsername||'';$('user-id').textContent=user.id;$('save-status').textContent=profile?'Profil zapisany w Supabase.':'Uzupełnij dane i zapisz swój pierwszy profil.';}
async function enter(){const g=++generation;const verified=await api.currentUser();const loaded=await api.loadProfile(verified.id);if(g!==generation)return;user=verified;profile=loaded;$('auth-view').hidden=true;$('profile-view').hidden=false;$('notice').hidden=true;paintProfile();await loadEvents();}
$('login-tab').onclick=()=>selectMode('login');$('signup-tab').onclick=()=>selectMode('signup');
$('show-password').onclick=()=>{const show=$('password').type==='password';$('password').type=show?'text':'password';$('show-password').textContent=show?'Ukryj':'Pokaż';$('show-password').setAttribute('aria-label',show?'Ukryj hasło':'Pokaż hasło');};
$('auth-form').onsubmit=e=>{e.preventDefault();busy($('auth-view'),async()=>{if(!api)throw new Error('Aplikacja nie jest jeszcze gotowa. Odśwież stronę.');const email=$('email').value.trim(),password=$('password').value;if(mode==='signup'){if(password!==$('repeat-password').value)throw new Error('Hasła muszą być takie same.');const data=await api.signUp(email,password);$('password').value='';$('repeat-password').value='';if(data?.access_token){await api.signIn(email,password);await enter();}else{selectMode('login');notify('Sprawdź skrzynkę e-mail i potwierdź adres. Potem wróć tutaj i zaloguj się. Jeśli adres ma już konto, możesz użyć dotychczasowego hasła.');}}else{await api.signIn(email,password);$('password').value='';await enter();}});};
$('resend').onclick=()=>busy($('auth-view'),async()=>{const email=$('email').value.trim();if(!$('email').checkValidity()||!email)throw new Error('Wpisz najpierw poprawny adres e-mail.');await api.resend(email);notify('Jeśli adres wymaga potwierdzenia, Supabase wyśle wiadomość. Sprawdź również spam.');});
$('profile-form').onsubmit=e=>{e.preventDefault();busy($('profile-view'),async()=>{const id=user?.id;if(!id)throw new Error('Zaloguj się ponownie.');const saved=await api.saveProfile(user,{full_name:$('full-name').value,username:$('username').value},Boolean(profile));if(user?.id!==id)return;profile=saved;paintProfile();notify('Twój profil został zapisany.');});};
$('reload-profile').onclick=()=>busy($('profile-view'),async()=>{await enter();notify('Profil odświeżony z bazy.');});
$('signout').onclick=()=>busy($('profile-view'),async()=>{generation++;let error;try{await api.signOut();}catch(e){error=e;}showAuth();notify(error?'Wylogowano z tej karty. Nie udało się potwierdzić unieważnienia sesji na serwerze.':'Wylogowano z tej karty.',Boolean(error));});
$('copy-id').onclick=()=>busy($('profile-view'),async()=>{await navigator.clipboard.writeText(user.id);notify('Identyfikator skopiowany.');});
$('test-access').onclick=()=>busy($('profile-view'),async()=>{const result=await api.auditRead(user,$('other-id').value.trim());const el=$('test-result');el.hidden=false;el.classList.toggle('error',result.leaked);el.textContent=result.leaked?'UWAGA: baza udostępniła cudzy profil. Przerwij testy i sprawdź polityki dostępu.':result.ownVisible?'Odczyt własnego profilu działa. Nie zwrócono cudzego profilu. Upewnij się, że profil drugiego konta został wcześniej zapisany.':'Nie zwrócono cudzych profili. Zapisz najpierw swój profil, aby zakończyć kontrolę.';});
async function boot(){try{api=createTogetherClient({url:SUPABASE_URL,key:SUPABASE_KEY});events=createEventsController(api,{render:renderEvents,report:eventError});await api.health();$('connection').textContent='Połączono z Supabase';if(await api.getSession())await enter();}catch(e){$('connection').textContent='Sprawdź połączenie';$('connection').classList.add('offline');notify(message(e),true);}}

function eventError(e){$('events-state').textContent='Nie udało się pobrać spotkań.';notify(e.code==='PGRST202'||e.code==='42P01'?'Moduł spotkań oczekuje na konfigurację bazy. Spróbuj ponownie później.':message(e),true);}
async function loadEvents(){if(!user||!events)return;$('events-state').textContent='Szukam spotkań…';await events.load({query:$('search-query').value,city:$('search-city').value,category:$('search-category').value,mine:$('search-mine').checked});}
function renderEvents(rows){
  $('events-list').replaceChildren();$('events-state').textContent=rows.length?rows.length+' spotkań przed Tobą':'Brak spotkań dla tych filtrów. Możesz zorganizować pierwsze.';
  for(const row of rows){const card=document.createElement('article');card.className='event-card';
    const add=(tag,text,cls)=>{const el=document.createElement(tag);el.textContent=text;if(cls)el.className=cls;card.append(el);};
    add('span',row.category,'event-category');add('h3',row.title);add('p',new Intl.DateTimeFormat('pl-PL',{dateStyle:'medium',timeStyle:'short'}).format(new Date(row.starts_at))+' · '+row.city);add('p',row.location);add('p',row.description,'event-description');add('p',row.attendee_count+' / '+row.capacity+' osób · '+(row.is_host?'Organizujesz':row.joined?'Dołączono':'Zapisy otwarte'),'event-meta');
    if(!row.is_host){const b=document.createElement('button');b.type='button';b.className='secondary';b.textContent=row.joined?'Zrezygnuj':row.attendee_count>=row.capacity?'Brak miejsc':'Dołącz do spotkania';b.disabled=!row.joined&&row.attendee_count>=row.capacity;b.onclick=()=>busy(card,async()=>{const leaving=row.joined;if(leaving)await events.leave(row.id);else await events.join(row.id);notify(leaving?'Zrezygnowano ze spotkania.':'Dołączono do spotkania.');await loadEvents();});card.append(b);} $('events-list').append(card);
  }
}
$('search-form').onsubmit=e=>{e.preventDefault();busy($('search-form'),loadEvents);};
$('event-form').onsubmit=e=>{e.preventDefault();busy($('event-form'),async()=>{await events.create(Object.fromEntries(new FormData(e.target)));e.target.reset();$('create-details').open=false;notify('Spotkanie utworzone. Jesteś organizatorem.');await loadEvents();});};
$('events-signout').onclick=()=>$('signout').click();
function selectPanel(account){$('events-panel').hidden=account;$('account-panel').hidden=!account;$('events-tab').classList.toggle('active',!account);$('account-tab').classList.toggle('active',account);$('events-tab').setAttribute('aria-pressed',String(!account));$('account-tab').setAttribute('aria-pressed',String(account));}
$('events-tab').onclick=()=>selectPanel(false);$('account-tab').onclick=()=>selectPanel(true);
boot();
